-- Data of the maps of the BerlinMOD-Hanoi section of Chapter 7, from the MobilityDB twins of the
-- listings (the queries of hanoi_figdata.sql without the WKB_BLOB casts), with their geometries in
-- longitude and latitude for Folium (the clipped trajectories of tripdistricts stay in EPSG:3857).
-- The trajectories drawn at city scale are simplified with a tolerance of 1 m (ST_Simplify), far
-- below a pixel of these maps; the meeting stretches of closetraj are drawn as computed.
\set ON_ERROR_STOP 1
SET TimeZone = 'UTC';
\copy (SELECT tripid, vehicleid, ST_AsText(ST_Transform(ST_Simplify(trajectory, 1.0), 4326)) AS traj FROM trips ORDER BY tripid) TO 'data/hanoi/trips.csv' CSV HEADER
\copy (SELECT municipalityid, municipalityname, ST_AsText(ST_Transform(municipalitygeo, 4326)) AS geo, ST_AsText(municipalitygeo) AS geo3857 FROM municipalities ORDER BY municipalityid) TO 'data/hanoi/municipalities.csv' CSV HEADER
\copy (WITH tripInt AS (SELECT vehicleid, tripid, COUNT(DISTINCT m.municipalityid) AS intersectCount FROM trips t, municipalities m WHERE eintersects(trip, municipalitygeo) GROUP BY vehicleid, tripid) SELECT t1.*, ST_AsText(ST_Transform(ST_Simplify(t.trajectory, 1.0), 4326)) AS trajectory FROM trips t JOIN tripInt t1 ON (t.tripId = t1.tripId AND t.vehicleid = t1.vehicleid) ORDER BY intersectCount DESC, t1.tripid LIMIT 5) TO 'data/hanoi/maxtripmuni.csv' CSV HEADER
\copy (select municipalityid, municipalityname, COUNT(*) as "intersectCount" from trips t, municipalities m where eintersects(t.trip, m.municipalitygeo) group by municipalityid, municipalityname order by 3 desc, municipalityid) TO 'data/hanoi/districtcount.csv' CSV HEADER
\copy (WITH Top6 AS (SELECT m.municipalityid, COUNT(*) AS c FROM trips t, municipalities m WHERE eintersects(t.trip, m.municipalitygeo) GROUP BY m.municipalityid ORDER BY c DESC, m.municipalityid LIMIT 6) SELECT m.municipalityname, t.tripid, ST_AsText(ST_Simplify(trajectory(atGeometry(t.trip, m.municipalitygeo)), 1.0)) AS "trajClip" FROM trips t, municipalities m, Top6 x WHERE m.municipalityid = x.municipalityid AND eintersects(t.trip, m.municipalitygeo) ORDER BY m.municipalityname, t.tripid) TO 'data/hanoi/districttrips.csv' CSV HEADER
\copy (SELECT m.MunicipalityName AS municipalityname, round((SUM(length(atGeometry(t.trip, m.MunicipalityGeo))) / 1000)::numeric, 3) AS "TotalKm" FROM Trips t, Municipalities m WHERE eintersects(t.trip, m.MunicipalityGeo) GROUP BY m.MunicipalityName ORDER BY 1) TO 'data/hanoi/totaldist.csv' CSV HEADER
\copy (SELECT DISTINCT t1.VehicleId AS "VehicleId1", t1.TripId AS "TripId1", ST_AsText(ST_Transform(ST_Simplify(t1.Trajectory, 1.0), 4326)) AS "Traj1", t2.VehicleId AS "VehicleId2", t2.TripId AS "TripId2", ST_AsText(ST_Transform(ST_Simplify(t2.Trajectory, 1.0), 4326)) AS "Traj2" FROM (SELECT * FROM trips ORDER BY TripId LIMIT 1000) t1, (SELECT * FROM trips ORDER BY TripId LIMIT 1000) t2 WHERE t1.VehicleId < t2.VehicleId AND eDwithin(t1.Trip, t2.Trip, 10.0) ORDER BY 1, 4, 2, 5) TO 'data/hanoi/closepairs.csv' CSV HEADER
\copy (WITH Temp AS (SELECT l1.Licence AS Licence1, t2.VehicleId AS Car2Id, whenTrue(tDwithin(t1.Trip, t2.Trip, 3.0)) AS Periods, atTime(t1.trip, whenTrue(tDwithin(t1.Trip, t2.Trip, 3.0))) as tt1, atTime(t2.trip, whenTrue(tDwithin(t1.Trip, t2.Trip, 3.0))) as tt2 FROM Trips t1, Licences1 l1, Trips t2, Vehicles v WHERE t1.VehicleId = l1.VehicleId AND t2.VehicleId = v.VehicleId AND t1.VehicleId <> t2.VehicleId AND t2.Trip && expandSpace(t1.trip::STBOX, 3.0)) SELECT Licence1 AS licence1, Car2Id AS car2id, ST_AsText(ST_Transform(trajectory(tt1), 4326)) AS geom1, ST_AsText(ST_Transform(trajectory(tt2), 4326)) AS geom2, Periods::text AS periods FROM Temp WHERE Periods IS NOT NULL ORDER BY 1, 2, 5) TO 'data/hanoi/closetraj.csv' CSV HEADER
\copy (SELECT DISTINCT t.TripId AS tripid, v.Licence AS licence, p.PointId AS pointid, ST_AsText(ST_Transform(p.Geom, 4326)) AS point, startTimestamp(atValue(t.Trip, p.Geom)) AS "Instant", ST_AsText(ST_Transform(ST_Simplify(t.trajectory, 1.0), 4326)) as trajectory FROM Trips t, Vehicles v, Points p WHERE t.VehicleId = v.VehicleId AND v.VehicleType = 'passenger' AND eIntersects(t.Trip, ST_Buffer(p.Geom,10))) TO 'data/hanoi/tripsinstants.csv' CSV HEADER
